"""Protocol boundary checks; generated bytes only, no cameras or ADB."""
import struct

import pytest

from deployment.phone_vision.android_usb import MAX_PACKET, receive_packet


class Fragments:
    def __init__(self, data):
        self.data=bytearray(data)

    def recv(self,size):
        part=bytes(self.data[:min(size,3)])
        del self.data[:len(part)]
        return part


def test_scrcpy5_session_header_is_not_consumed_as_video_payload():
    packet=struct.pack('>III',0x80000000,1280,720)
    assert receive_packet(Fragments(packet))==(None,False,b'')


def test_scrcpy5_config_and_keyframe_flags_preserve_source_timestamp():
    payload=b'generated-packet'
    for flag,config in ((1<<62,True),(1<<61,False),(0,False)):
        packet=struct.pack('>QI',flag|1234567,len(payload))+payload
        assert receive_packet(Fragments(packet))==(1234567,config,payload)


@pytest.mark.parametrize('size',[0,MAX_PACKET+1])
def test_invalid_packet_size_rejected_without_reading_payload(size):
    with pytest.raises(ValueError,match='packet size'):
        receive_packet(Fragments(struct.pack('>QI',12,size)))


def test_disconnect_mid_frame_is_an_error():
    with pytest.raises(EOFError):
        receive_packet(Fragments(struct.pack('>QI',12,100)+b'partial'))
